          />

          <select
            value={statusFilter}
            onChange={(e) =>
              setStatusFilter(
                e.target.value as "ALL" | TaskStatus
              )
            }
            className="border rounded-lg px-4 py-3"
          >
            <option value="ALL">
              All statuses
            </option>

            <option value="TODO">
              TODO
            </option>

            <option value="IN_PROGRESS">
              IN PROGRESS
            </option>

            <option value="DONE">
              DONE
            </option>
          </select>

          <select
            value={priorityFilter}
            onChange={(e) =>
              setPriorityFilter(
                e.target.value as "ALL" | TaskPriority
              )
            }
            className="border rounded-lg px-4 py-3"
          >
            <option value="ALL">
              All priorities
            </option>

            <option value="LOW">
              LOW
            </option>

            <option value="MEDIUM">
              MEDIUM
            </option>

            <option value="HIGH">
              HIGH
            </option>
          </select>
        </div>

        <div className="mt-4 text-sm text-gray-500">
          Showing{" "}
          <span className="font-semibold text-gray-900">
            {filteredTasks.length}
          </span>{" "}
          of{" "}
          <span className="font-semibold text-gray-900">
            {totalTasks}
          </span>{" "}
          tasks
        </div>
      </div>
    </section>
  );
}

function StatCard({
  label,
  value,
  icon,
}: {
  label: string;
