          <span className="text-xs px-2 py-1 rounded-full bg-gray-100">
            📅{" "}
            {task.dueDate.toLocaleDateString()}
          </span>
        )}
      </div>

      <div
        className="mt-4"
        onPointerDown={(e) =>
          e.stopPropagation()
        }
      >
        <TaskStatus
          taskId={task.id}
          status={task.status}
        />
      </div>
    </div>
  );
}


