    return (
      task.dueDate < now &&
      task.status !== "DONE"
    );
  }).length;

  /*
   * -------------------------
   * PROJECT HEALTH
   * -------------------------
   */

  let projectHealth = "On track";

  if (overdueTasks > 0) {
