import "server-only";

import { prisma } from "@/lib/prisma";

import { AiAuthorizationError } from "../core/errors";
import type { AiScope } from "../schemas/requests";

const MAX_WORKSPACES = 12;
const MAX_PROJECTS_PER_WORKSPACE = 20;
const MAX_TASKS_PER_PROJECT = 50;
const MAX_ACTIVITIES_PER_TASK = 4;

export interface AiBusinessContext {
  business: {
    id: string;
    name: string;
    type: string;
  };
  workspaces: Array<{
    id: string;
    name: string;
    description: string | null;
    projects: Array<{
      id: string;
      name: string;
      description: string | null;
      tasks: Array<{
        id: string;
        title: string;
        description: string | null;
        status: string;
        priority: string;
        dueDate: string | null;
        activities: Array<{
          type: string;
          message: string;
          createdAt: string;
        }>;
      }>;
    }>;
  }>;
}

export async function loadBusinessContext(
  businessId: string,
  scope?: AiScope
): Promise<AiBusinessContext> {
  const business = await prisma.business.findUnique({
    where: { id: businessId },
    select: {
      id: true,
      businessName: true,
      businessType: true,
    },
  });

  if (!business) {
    throw new AiAuthorizationError("Your business account could not be found.");
  }

  const workspaces = await prisma.workspace.findMany({
    where: {
      businessId,
      ...(scope?.workspaceId ? { id: scope.workspaceId } : {}),
    },
    orderBy: { updatedAt: "desc" },
    take: MAX_WORKSPACES,
    select: {
      id: true,
      name: true,
      description: true,
      projects: {
        where: scope?.projectId ? { id: scope.projectId } : undefined,
        orderBy: { updatedAt: "desc" },
        take: MAX_PROJECTS_PER_WORKSPACE,
        select: {
          id: true,
          name: true,
          description: true,
          tasks: {
            orderBy: { updatedAt: "desc" },
            take: MAX_TASKS_PER_PROJECT,
            select: {
              id: true,
              title: true,
              description: true,
              status: true,
              priority: true,
              dueDate: true,
              activities: {
                orderBy: { createdAt: "desc" },
                take: MAX_ACTIVITIES_PER_TASK,
                select: {
                  type: true,
                  message: true,
                  createdAt: true,
                },
              },
            },
          },
        },
      },
    },
  });

  if (scope?.workspaceId && workspaces.length === 0) {
    throw new AiAuthorizationError("Workspace not found.");
  }

  if (
    scope?.projectId &&
    !workspaces.some((workspace) =>
      workspace.projects.some((project) => project.id === scope.projectId)
    )
  ) {
    throw new AiAuthorizationError("Project not found.");
  }

  return {
    business: {
      id: business.id,
      name: business.businessName,
      type: business.businessType,
    },
    workspaces: workspaces.map((workspace) => ({
      ...workspace,
      projects: workspace.projects.map((project) => ({
        ...project,
        tasks: project.tasks.map((task) => ({
          ...task,
          dueDate: task.dueDate?.toISOString() ?? null,
          activities: task.activities.map((activity) => ({
            ...activity,
            createdAt: activity.createdAt.toISOString(),
          })),
        })),
      })),
    })),
  };
}

import type { AiBusinessContext } from "./loadBusinessContext";

export function workspaceReference(id: string) {
  return `workspace:${id}`;
}

export function projectReference(id: string) {
  return `project:${id}`;
}

export function taskReference(id: string) {
  return `task:${id}`;
}

export function contextForModel(context: AiBusinessContext) {
  return {
    business: {
      name: context.business.name,
      type: context.business.type,
    },
    workspaces: context.workspaces.map((workspace) => ({
      ref: workspaceReference(workspace.id),
      name: workspace.name,
      description: workspace.description,
      projects: workspace.projects.map((project) => ({
        ref: projectReference(project.id),
        name: project.name,
        description: project.description,
        tasks: project.tasks.map((task) => ({
          ref: taskReference(task.id),
          title: task.title,
          description: task.description,
          status: task.status,
          priority: task.priority,
          dueDate: task.dueDate,
          recentActivity: task.activities,
        })),
      })),
    })),
  };
}

