import { z } from "zod";

export const aiIntentSchema = z.enum([
  "assistant",
  "plan",
  "progress",
  "priorities",
  "insights",
]);

export const aiScopeSchema = z
  .object({
    workspaceId: z.string().cuid().optional(),
    projectId: z.string().cuid().optional(),
  })
  .strict();

export const aiRequestSchema = z
  .object({
    intent: aiIntentSchema,
    message: z.string().trim().min(1).max(4_000).optional(),
    scope: aiScopeSchema.optional(),
  })
  .strict();

export type AiIntent = z.infer<typeof aiIntentSchema>;
export type AiScope = z.infer<typeof aiScopeSchema>;
export type AiRequest = z.infer<typeof aiRequestSchema>;

import { z } from "zod";

const entityReferenceSchema = z
  .string()
  .regex(/^(workspace|project|task):[a-z0-9]+$/, "Invalid entity reference.");

const taskStatusSchema = z.enum(["TODO", "IN_PROGRESS", "DONE"]);
const taskPrioritySchema = z.enum(["LOW", "MEDIUM", "HIGH"]);

const actionBaseSchema = z.object({
  label: z.string().trim().min(1).max(160),
  rationale: z.string().trim().min(1).max(500).optional(),
});

export const aiActionProposalSchema = z.discriminatedUnion("type", [
  actionBaseSchema.extend({
    type: z.literal("create_project"),
    workspaceRef: entityReferenceSchema,
    name: z.string().trim().min(1).max(120),
    description: z.string().trim().max(2_000).optional(),
  }),
  actionBaseSchema.extend({
    type: z.literal("create_task"),
    projectRef: entityReferenceSchema,
    title: z.string().trim().min(1).max(160),
    description: z.string().trim().max(2_000).optional(),
    priority: taskPrioritySchema.default("MEDIUM"),
    dueDate: z.string().date().optional(),
  }),
  actionBaseSchema.extend({
    type: z.literal("update_task_status"),
    taskRef: entityReferenceSchema,
    status: taskStatusSchema,
  }),
  actionBaseSchema.extend({
    type: z.literal("update_task_priority"),
    taskRef: entityReferenceSchema,
    priority: taskPrioritySchema,
  }),
  actionBaseSchema.extend({
    type: z.literal("delete_task"),
    taskRef: entityReferenceSchema,
    requiresConfirmation: z.literal(true),
  }),
  actionBaseSchema.extend({
    type: z.literal("delete_project_tasks"),
    projectRef: entityReferenceSchema,
    requiresConfirmation: z.literal(true),
  }),
]);

export const confirmedAiActionSchema = z.discriminatedUnion("type", [
  aiActionProposalSchema.options[0].extend({ confirmed: z.literal(true) }),
  aiActionProposalSchema.options[1].extend({ confirmed: z.literal(true) }),
  aiActionProposalSchema.options[2].extend({ confirmed: z.literal(true) }),
  aiActionProposalSchema.options[3].extend({ confirmed: z.literal(true) }),
  aiActionProposalSchema.options[4].extend({ confirmed: z.literal(true) }),
  aiActionProposalSchema.options[5].extend({ confirmed: z.literal(true) }),
]);

export type AiActionProposal = z.infer<typeof aiActionProposalSchema>;
export type ConfirmedAiAction = z.infer<typeof confirmedAiActionSchema>;

export type EntityReferenceType = "workspace" | "project" | "task";

export function parseEntityReference(
  reference: string,
  expectedType: EntityReferenceType
) {
  const [type, id] = reference.split(":", 2);

  if (type !== expectedType || !id) {
    return null;
  }

  return id;
}

