import "server-only";

import { getCurrentBusiness } from "@/lib/auth/business";
import { prisma } from "@/lib/prisma";

import {
  AiActionError,
  AiAuthenticationError,
} from "../core/errors";
import type { ConfirmedAiAction } from "../schemas/actions";
import {
  requireOwnedProject,
  requireOwnedTask,
  requireOwnedWorkspace,
} from "./ownership";

export async function executeConfirmedAiAction(action: ConfirmedAiAction) {
  // Re-authenticate inside the mutation boundary; a route caller cannot supply a business ID.
  const business = await getCurrentBusiness();

  if (!business) {
    throw new AiAuthenticationError();
  }

  switch (action.type) {
    case "create_project": {
      const workspace = await requireOwnedWorkspace(
        business.id,
        action.workspaceRef
      );
      const project = await prisma.project.create({
        data: {
          name: action.name,
          description: action.description,
          workspaceId: workspace.id,
        },
      });

      return { type: action.type, project };
    }

    case "create_task": {
      const project = await requireOwnedProject(business.id, action.projectRef);
      const task = await prisma.$transaction(async (tx) => {
        const createdTask = await tx.task.create({
          data: {
            title: action.title,
            description: action.description,
            projectId: project.id,
            priority: action.priority,
            dueDate: action.dueDate ? new Date(action.dueDate) : null,
          },
        });

        await tx.taskActivity.create({
          data: {
            taskId: createdTask.id,
            type: "CREATED",
            message: `Task "${createdTask.title}" was created.`,
          },
        });

        return createdTask;
      });

      return { type: action.type, task };
    }

    case "update_task_status": {
      const existingTask = await requireOwnedTask(business.id, action.taskRef);

      if (existingTask.status === action.status) {
        return { type: action.type, task: existingTask, unchanged: true };
      }

      const task = await prisma.$transaction(async (tx) => {
        const updatedTask = await tx.task.update({
          where: { id: existingTask.id },
          data: { status: action.status },
        });

        await tx.taskActivity.create({
          data: {
            taskId: updatedTask.id,
            type: "STATUS_CHANGED",
            message: `Status changed from ${existingTask.status} to ${updatedTask.status}.`,
          },
        });

        return updatedTask;
      });

      return { type: action.type, task };
    }

    case "update_task_priority": {
      const existingTask = await requireOwnedTask(business.id, action.taskRef);

      if (existingTask.priority === action.priority) {
        return { type: action.type, task: existingTask, unchanged: true };
      }

      const task = await prisma.$transaction(async (tx) => {
        const updatedTask = await tx.task.update({
          where: { id: existingTask.id },
          data: { priority: action.priority },
        });

        await tx.taskActivity.create({
          data: {
            taskId: updatedTask.id,
            type: "PRIORITY_CHANGED",
            message: `Priority changed from ${existingTask.priority} to ${updatedTask.priority}.`,
          },
        });

        return updatedTask;
      });

      return { type: action.type, task };
    }

    case "delete_task": {
      const task = await requireOwnedTask(business.id, action.taskRef);

      await prisma.$transaction(async (tx) => {
        await tx.taskActivity.deleteMany({ where: { taskId: task.id } });
        await tx.task.delete({ where: { id: task.id } });
      });

      return { type: action.type, deletedTaskId: task.id };
    }

    case "delete_project_tasks": {
      const project = await requireOwnedProject(business.id, action.projectRef);

      const deletedTaskCount = await prisma.$transaction(async (tx) => {
        const tasks = await tx.task.findMany({
          where: { projectId: project.id },
          select: { id: true },
        });
        const taskIds = tasks.map((task) => task.id);

        if (taskIds.length === 0) {
          return 0;
        }

        await tx.taskActivity.deleteMany({
          where: { taskId: { in: taskIds } },
        });
        const deleted = await tx.task.deleteMany({
          where: { id: { in: taskIds }, projectId: project.id },
        });

        return deleted.count;
      });

      return { type: action.type, deletedTaskCount };
    }

    default:
      throw new AiActionError("This AI action is not supported.");
  }
}

import "server-only";

import { prisma } from "@/lib/prisma";

import {
  AiAuthorizationError,
  AiValidationError,
} from "../core/errors";
import { parseEntityReference } from "../schemas/actions";

function requireReference(
  reference: string,
  type: "workspace" | "project" | "task"
) {
  const id = parseEntityReference(reference, type);

  if (!id) {
    throw new AiValidationError("The action contains an invalid target.");
  }

  return id;
}

export async function requireOwnedWorkspace(
  businessId: string,
  workspaceRef: string
) {
  const id = requireReference(workspaceRef, "workspace");
  const workspace = await prisma.workspace.findFirst({
    where: { id, businessId },
  });

  if (!workspace) {
    throw new AiAuthorizationError("Workspace not found.");
  }

  return workspace;
}

export async function requireOwnedProject(
  businessId: string,
  projectRef: string
) {
  const id = requireReference(projectRef, "project");
  const project = await prisma.project.findFirst({
    where: {
      id,
      workspace: { businessId },
    },
  });

  if (!project) {
    throw new AiAuthorizationError("Project not found.");
  }

  return project;
}

export async function requireOwnedTask(businessId: string, taskRef: string) {
  const id = requireReference(taskRef, "task");
  const task = await prisma.task.findFirst({
    where: {
      id,
      project: {
        workspace: { businessId },
      },
    },
  });

  if (!task) {
    throw new AiAuthorizationError("Task not found.");
  }

  return task;
}

