    try {
      const request = {
        intent,
        ...(needsMessage ? { message: message.trim() } : {}),
        ...(scope ? { scope } : {}),
      };
      const apiResponse = await fetch("/api/ai", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(request),
      });
      const data = await apiResponse.json();

      if (!apiResponse.ok || !data.success) {
        throw new Error(data.message || "Pulse AI could not complete that request.");
      }

      setResponse(data.response);
    } catch (requestError) {
      setError(
        requestError instanceof Error
          ? requestError.message
          : "Pulse AI could not complete that request."
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <section className="mb-8 rounded-2xl border bg-white p-6 shadow-sm">
      <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <p className="text-sm font-medium text-gray-500">Pulse AI</p>
          <h2 className="text-2xl font-bold">Business copilot</h2>
          <p className="mt-1 text-sm text-gray-600">
            Recommendations are grounded in this business&apos;s current workspace data.
          </p>
        </div>
        <select
          value={intent}
          onChange={(event) => setIntent(event.target.value as AiIntent)}
          className="rounded-lg border px-3 py-2"
          aria-label="Pulse AI request type"
        >
          {Object.entries(intentLabels).map(([value, label]) => (
            <option key={value} value={value}>
              {label}
            </option>
          ))}
        </select>
      </div>

      {needsMessage && (
        <textarea
          value={message}
          onChange={(event) => setMessage(event.target.value)}
          placeholder={
            intent === "plan"
              ? "Describe the outcome you want to plan for..."
              : "Ask about this project, its work, or priorities..."
          }
          className="mt-5 min-h-24 w-full rounded-lg border p-3"
        />
      )}

      {error && <p className="mt-3 text-sm text-red-600">{error}</p>}

      <button
        type="button"
        disabled={loading}
        onClick={runAi}
        className="mt-4 rounded-lg bg-black px-4 py-2 font-medium text-white hover:bg-gray-800 disabled:opacity-50"
      >
        {loading ? "Thinking..." : intentLabels[intent]}
      </button>

      {response && (
        <div className="mt-6 rounded-xl bg-gray-50 p-5">
          <p className="whitespace-pre-wrap text-gray-800">{response.summary}</p>

          {response.highlights.length > 0 && (
            <div className="mt-5">
              <h3 className="font-semibold">Highlights</h3>
              <ul className="mt-2 list-disc space-y-1 pl-5 text-sm text-gray-700">
                {response.highlights.map((highlight, index) => (
                  <li key={index}>{highlight}</li>
                ))}
              </ul>
            </div>
          )}

          {response.recommendations.length > 0 && (
            <div className="mt-5">
              <h3 className="font-semibold">Recommendations</h3>
              <ul className="mt-2 list-disc space-y-1 pl-5 text-sm text-gray-700">
                {response.recommendations.map((recommendation, index) => (
                  <li key={index}>{recommendation}</li>
                ))}
              </ul>
            </div>
          )}

          <AiActionConfirmation
            actions={response.actions}
            onComplete={() => window.location.reload()}
          />
        </div>
      )}
    </section>
  );
}

"use client";

import { useState } from "react";

import type { AiActionProposal } from "@/lib/ai/schemas/actions";

const destructiveActions = new Set<AiActionProposal["type"]>([
  "delete_task",
  "delete_project_tasks",
]);

export default function AiActionConfirmation({
  actions,
  onComplete,
}: {
  actions: AiActionProposal[];
  onComplete: () => void;
}) {
  const [pendingAction, setPendingAction] = useState<AiActionProposal | null>(
    null
  );
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function confirmAction() {
    if (!pendingAction) return;

    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/ai/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...pendingAction, confirmed: true }),
      });
      const data = await response.json();

      if (!response.ok || !data.success) {
        throw new Error(data.message || "Unable to complete this AI action.");
      }

      setPendingAction(null);
      onComplete();
    } catch (requestError) {
      setError(
        requestError instanceof Error
          ? requestError.message
          : "Unable to complete this AI action."
      );
    } finally {
      setLoading(false);
    }
  }

  if (actions.length === 0) return null;

  return (
    <section className="mt-5 border-t pt-5">
      <h3 className="font-semibold">Proposed actions</h3>
      <p className="mt-1 text-sm text-gray-500">
        Pulse AI cannot make changes until you explicitly confirm one.
      </p>

      <div className="mt-3 space-y-3">
        {actions.map((action, index) => (
          <div key={`${action.type}-${index}`} className="rounded-lg border p-3">
            <p className="font-medium">{action.label}</p>
            {action.rationale && (
              <p className="mt-1 text-sm text-gray-600">{action.rationale}</p>
            )}
            <button
              type="button"
              onClick={() => setPendingAction(action)}
              className={`mt-3 rounded-lg px-3 py-2 text-sm font-medium text-white ${
                destructiveActions.has(action.type)
                  ? "bg-red-600 hover:bg-red-700"
                  : "bg-black hover:bg-gray-800"
              }`}
            >
              Review and confirm
            </button>
          </div>
        ))}
      </div>

      {pendingAction && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <h3 className="text-xl font-bold">Confirm AI action</h3>
            <p className="mt-3 text-gray-700">{pendingAction.label}</p>
            {destructiveActions.has(pendingAction.type) && (
              <p className="mt-3 rounded-lg bg-red-50 p-3 text-sm text-red-700">
                This is destructive and cannot be undone from this screen.
              </p>
            )}
            {error && <p className="mt-3 text-sm text-red-600">{error}</p>}
            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                disabled={loading}
                onClick={() => {
                  setPendingAction(null);
                  setError("");
                }}
                className="rounded-lg border px-4 py-2 disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={loading}
                onClick={confirmAction}
                className={`rounded-lg px-4 py-2 text-white disabled:opacity-50 ${
                  destructiveActions.has(pendingAction.type)
                    ? "bg-red-600"
                    : "bg-black"
                }`}
              >
                {loading ? "Applying..." : "Confirm action"}
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

